class RateLimiter:
    def __init__(self, limit, window):
        self.limit = limit
        self.window = window
        self.hits = {}

    def allow(self, key, now):
        recent = [t for t in self.hits.get(key, []) if now - t < self.window]
        if len(recent) >= self.limit:
            self.hits[key] = recent
            return False
        recent.append(now)
        self.hits[key] = recent
        return True

limiter = RateLimiter(3, 10)
for t in [0, 1, 2, 3, 11, 12]:
    print(t, limiter.allow("anna", t))

PERMISSIONS = {
    "viewer": {"read"},
    "editor": {"read", "write"},
    "admin": {"read", "write", "delete"},
}


def can(role, action):
    return action in PERMISSIONS.get(role, set())

def has_scopes(granted, required):
    def covered(scope):
        for g in granted:
            if g == scope:
                return True
            if g.endswith(":*") and scope.startswith(g[:-1]):
                return True
        return False

    return all(covered(scope) for scope in required)
